// Command patchtypes adjusts the Go types generated by the grafana-app-sdk so they keep the shapes the
// provisioning code, the k8s client generators and the served OpenAPI rely on: unprefixed nested type
// names, shared types, plain optional scalars, metav1.Condition, typed secure values and k8s markers.
//
// It runs after `grafana-app-sdk generate` (see the Makefile) on the freshly written files.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"golang.org/x/tools/imports"
)

var kinds = []string{"Repository", "Connection", "Job", "HistoricJob"}

// handWritten maps generated enum types to the hand-written enum they are replaced with. The hand-written
// declarations (and their constants) stay in types.go and friends.
var handWritten = map[string]string{
	"RepositoryCommitOptionsSigningMethod": "SigningMethod",
	"RepositorySyncOptionsTarget":          "SyncTargetType",
	"RepositorySpecWorkflows":              "Workflow",
	"RepositorySpecType":                   "RepositoryType",
	"RepositorySyncStatusState":            "JobState",
	"RepositoryHealthStatusError":          "HealthFailureType",
	"ConnectionHealthStatusError":          "HealthFailureType",
	"RepositoryDeletionStatusCause":        "DeletionCause",
	"ConnectionSpecType":                   "ConnectionType",
	"JobSpecAction":                        "JobAction",
	"HistoricJobSpecAction":                "JobAction",
	"JobStatusState":                       "JobState",
	"HistoricJobStatusState":               "JobState",
	"RepositoryErrorDetails":               "ErrorDetails",
	"ConnectionErrorDetails":               "ErrorDetails",
	"RepositoryCondition":                  "metav1.Condition",
	"ConnectionCondition":                  "metav1.Condition",
	"RepositoryConditionStatus":            "",
	"ConnectionConditionStatus":            "",
}

// sharedWithJob types are one type in the hand-written code: HistoricJob reuses the Job ones.
var historicAliases = map[string]string{"HistoricJobSpec": "JobSpec", "HistoricJobStatus": "JobStatus"}

// fieldTypes overrides a generated field type ("Struct.Field"), with the tag suffix to use.
var fieldTypes = map[string]string{
	"PullRequestJobOptions.PR":       "int",
	"TestJobOptions.ProgressUpdates": "int",
	"TestJobOptions.Duration":        "metav1.Duration",
	"JobStatus.Summary":              "[]*JobResourceSummary",
	"RepositoryStatus.Webhook":       "*WebhookStatus",
	"DeletionStatus.State":           "DeletionState",
	"RepositoryStatus.Conditions":    "[]metav1.Condition",
	"ConnectionStatus.Conditions":    "[]metav1.Condition",
	"RepositorySpec.Workflows":       "[]Workflow",
	"RepositoryStatus.Quota":         "QuotaStatus",
	"RepositoryStatus.Token":         "TokenStatus",
	"ConnectionStatus.Token":         "TokenStatus",
}

// fieldNames renames generated Go field names ("Struct.Field") to the established ones.
var fieldNames = map[string]string{
	"BitbucketRepositoryConfig.Url":                   "URL",
	"CommitOptions.SmimeCertificate":                  "SMIMECertificate",
	"ConnectionSpec.Github":                           "GitHub",
	"ConnectionSpec.GithubEnterprise":                 "GitHubEnterprise",
	"ConnectionSpec.GithubEnterpriseOAuth":            "GitHubEnterpriseOAuth",
	"ConnectionSpec.Oauth":                            "OAuth",
	"ConnectionSpec.Url":                              "URL",
	"GitHubEnterpriseConnectionConfig.ServerUrl":      "ServerURL",
	"GitHubEnterpriseOAuthConnectionConfig.ServerUrl": "ServerURL",
	"GitHubEnterpriseRepositoryConfig.ServerUrl":      "ServerURL",
	"GitHubEnterpriseRepositoryConfig.Url":            "URL",
	"GitHubRepositoryConfig.Url":                      "URL",
	"GitLabRepositoryConfig.Url":                      "URL",
	"GitRepositoryConfig.Url":                         "URL",
	"JobSpec.Pr":                                      "PullRequest",
	"JobStatus.Url":                                   "URLs",
	"PullRequestJobOptions.Pr":                        "PR",
	"PullRequestJobOptions.Url":                       "URL",
	"RepositorySpec.Github":                           "GitHub",
	"RepositorySpec.GithubEnterprise":                 "GitHubEnterprise",
	"RepositorySpec.Gitlab":                           "GitLab",
	"SyncStatus.Job":                                  "JobID",
	"WebhookConfig.BaseUrl":                           "BaseURL",
	"WebhookStatus.Id":                                "ID",
	"WebhookStatus.Url":                               "URL",
	"WebhookStatus.Uuid":                              "UUID",
}

// keepPointer lists optional scalar fields that stay pointers.
var keepPointer = map[string]bool{"PullRequestJobOptions.IsFork": true}

// extraMarkers adds comment lines before a field ("Struct.Field").
var extraMarkers = map[string][]string{
	"RepositoryStatus.Conditions": {"+listType=map", "+listMapKey=type", "+patchMergeKey=type", "+patchStrategy=merge"},
	"ConnectionStatus.Conditions": {"+listType=map", "+listMapKey=type", "+patchMergeKey=type", "+patchStrategy=merge"},
}

// tagOverrides replaces the json tag value ("Struct.Field").
var tagOverrides = map[string]string{
	"RepositoryStatus.Webhook":    `json:"webhook"`,
	"RepositoryStatus.Conditions": `json:"conditions,omitempty" patchStrategy:"merge" patchMergeKey:"type"`,
	"ConnectionStatus.Conditions": `json:"conditions,omitempty" patchStrategy:"merge" patchMergeKey:"type"`,
}

type decl struct {
	start, end int
	names      []string // type names declared, or func/receiver names
	kind       string   // "type", "func", "const", "other"
	recv       string
	fn         string
}

//nolint:gocyclo // code generation tool, a linear pipeline of steps
func main() {
	dir := os.Args[1]
	files, _ := filepath.Glob(filepath.Join(dir, "*_gen.go"))
	targets := make([]string, 0, len(files))
	for _, f := range files {
		b := filepath.Base(f)
		for _, k := range kinds {
			p := strings.ToLower(k) + "_"
			if strings.HasPrefix(b, p) {
				targets = append(targets, f)
			}
		}
	}
	sort.Strings(targets)
	// The app-sdk resource clients are not used: the provisioning code uses the k8s typed clientset.
	for _, f := range files {
		if strings.HasSuffix(f, "_client_gen.go") {
			must(os.Remove(f)) //nolint:gosec // the files are generated output in the package directory
		}
	}
	kept := make([]string, 0, len(targets))
	for _, f := range targets {
		if !strings.HasSuffix(f, "_client_gen.go") {
			kept = append(kept, f)
		}
	}
	targets = kept

	src := map[string][]byte{}
	decls := map[string][]decl{}
	for _, f := range targets {
		b, err := os.ReadFile(f) //nolint:gosec // the files are generated output in the package directory
		must(err)
		src[f] = b
		decls[f] = parse(f, b)
	}

	// 1. work out renames and deletions
	rename := map[string]string{}
	deleteType := map[string]bool{}
	owner := map[string]string{} // base name -> kind that owns it
	for _, k := range kinds {
		for _, f := range targets {
			if !strings.HasPrefix(filepath.Base(f), strings.ToLower(k)+"_") || (!strings.HasSuffix(f, "_spec_gen.go") && !strings.HasSuffix(f, "_status_gen.go")) {
				continue
			}
			for _, d := range decls[f] {
				if d.kind != "type" {
					continue
				}
				n := d.names[0]
				switch {
				case handWritten[n] != "" || (strings.Contains(n, "ConditionStatus") && containsKey(handWritten, n)):
					deleteType[n] = true
					rename[n] = handWritten[n]
				case containsKey(handWritten, n):
					deleteType[n] = true
				case historicAliases[n] != "":
					deleteType[n] = true
					rename[n] = historicAliases[n]
				case n == k+"Spec" || n == k+"Status":
				default:
					base := strings.TrimPrefix(n, k)
					if o, ok := owner[base]; ok && o != k {
						deleteType[n] = true
					} else {
						owner[base] = k
					}
					rename[n] = base
				}
			}
		}
	}
	// delete types whose base is owned by an earlier kind keep a rename to the shared base.
	for n := range deleteType {
		if _, ok := rename[n]; !ok {
			for _, k := range kinds {
				if strings.HasPrefix(n, k) && n != k {
					rename[n] = strings.TrimPrefix(n, k)
				}
			}
		}
	}
	// kind-level HistoricJob prefixed names that map to shared Job names
	_ = owner

	renameRe := buildRenameRe(rename)
	for _, f := range targets {
		out := patch(f, src[f], decls[f], deleteType, renameRe, rename)
		must(os.WriteFile(f, out, 0o644)) //nolint:gosec // the files are generated output in the package directory
	}
	// fix imports and formatting
	for _, f := range targets {
		b, err := os.ReadFile(f) //nolint:gosec // the files are generated output in the package directory
		must(err)
		out, err := imports.Process(f, b, nil)
		must(err)
		must(os.WriteFile(f, out, 0o644)) //nolint:gosec // the files are generated output in the package directory
	}
}

// normaliseKindTags makes the kind and list envelopes serialise like the hand-written ones: spec, status and
// metadata are optional on the wire.
func normaliseKindTags(l, cur string) string {
	for _, f := range []string{"metadata", "spec", "status"} {
		l = strings.Replace(l, `json:"`+f+`" yaml:"`+f+`"`, `json:"`+f+`,omitempty" yaml:"`+f+`"`, 1)
	}
	return l
}

// emptySubresources removes the status subresource of kinds whose status is written through the main resource.
func emptySubresources(text, kind string) string {
	text = regexp.MustCompile(`(?s)func \(o \*`+kind+`\) GetSubresources\(\) map\[string\]any \{.*?\n\}\n`).
		ReplaceAllString(text, "func (o *"+kind+") GetSubresources() map[string]any {\n\treturn map[string]any{}\n}\n")
	text = regexp.MustCompile(`(?s)func \(o \*`+kind+`\) GetSubresource\(name string\) \(any, bool\) \{.*?\n\}\n`).
		ReplaceAllString(text, "func (o *"+kind+") GetSubresource(string) (any, bool) {\n\treturn nil, false\n}\n")
	text = regexp.MustCompile(`(?s)func \(o \*`+kind+`\) SetSubresource\(name string, value any\) error \{.*?\n\}\n`).
		ReplaceAllString(text, "func (o *"+kind+") SetSubresource(name string, _ any) error {\n\treturn fmt.Errorf(\"subresource '%s' does not exist\", name)\n}\n")
	return text
}

func containsKey(m map[string]string, k string) bool { _, ok := m[k]; return ok }

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func buildRenameRe(rename map[string]string) *regexp.Regexp {
	names := make([]string, 0, len(rename))
	for n := range rename {
		names = append(names, regexp.QuoteMeta(n))
	}
	sort.Slice(names, func(i, j int) bool { return len(names[i]) > len(names[j]) })
	return regexp.MustCompile(`\b(` + strings.Join(names, "|") + `)\b`)
}

func parse(path string, b []byte) []decl {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, b, parser.ParseComments)
	must(err)
	var out []decl
	for _, d := range f.Decls {
		start := d.Pos()
		switch x := d.(type) {
		case *ast.GenDecl:
			if x.Doc != nil {
				start = x.Doc.Pos()
			}
			dd := decl{start: fset.Position(start).Offset, end: fset.Position(x.End()).Offset}
			switch x.Tok {
			case token.TYPE:
				dd.kind = "type"
				for _, s := range x.Specs {
					dd.names = append(dd.names, s.(*ast.TypeSpec).Name.Name)
				}
			case token.CONST:
				dd.kind = "const"
				for _, s := range x.Specs {
					vs := s.(*ast.ValueSpec)
					if id, ok := vs.Type.(*ast.Ident); ok {
						dd.names = append(dd.names, id.Name)
					}
				}
			default:
				dd.kind = "other"
			}
			out = append(out, dd)
		case *ast.FuncDecl:
			if x.Doc != nil {
				start = x.Doc.Pos()
			}
			dd := decl{start: fset.Position(start).Offset, end: fset.Position(x.End()).Offset, kind: "func", fn: x.Name.Name}
			if x.Recv != nil && len(x.Recv.List) > 0 {
				t := x.Recv.List[0].Type
				if s, ok := t.(*ast.StarExpr); ok {
					t = s.X
				}
				if id, ok := t.(*ast.Ident); ok {
					dd.recv = id.Name
				}
			}
			out = append(out, dd)
		}
	}
	return out
}

var (
	structRe  = regexp.MustCompile(`^type (\w+) struct`)
	fieldRe   = regexp.MustCompile("^\t([A-Z]\\w*)\\s+(\\S.*?)\\s+(`.*`)\\s*$")
	scalarPtr = regexp.MustCompile(`^\*(string|bool|int64|float64)$`)
)

//nolint:gocyclo,gocognit // code generation tool, a linear pipeline of text edits
func patch(path string, b []byte, ds []decl, deleteType map[string]bool, re *regexp.Regexp, rename map[string]string) []byte {
	isObject := strings.HasSuffix(path, "_object_gen.go")
	isTypes := strings.HasSuffix(path, "_spec_gen.go") || strings.HasSuffix(path, "_status_gen.go")
	// cut deleted ranges (back to front)
	type cut struct{ s, e int }
	var cuts []cut
	for _, d := range ds {
		del := false
		switch d.kind {
		case "type":
			for _, n := range d.names {
				if deleteType[n] {
					del = true
				}
			}
		case "const":
			for _, n := range d.names {
				if deleteType[n] {
					del = true
				}
			}
		case "func":
			if deleteType[d.recv] {
				del = true
			}
			for n := range deleteType {
				if d.fn == "New"+n {
					del = true
				}
			}
			if isTypes && (d.fn == "DeepCopy" || d.fn == "DeepCopyInto") {
				del = true
			}
			if isTypes && strings.HasPrefix(d.fn, "New") && d.recv == "" {
				del = true
			}
			if isObject && d.recv != "" {
				switch d.fn {
				case "DeepCopyObject", "DeepCopy", "DeepCopyInto", "GetSecureValues", "SetSecureValues":
					del = true
				}
			}
		}
		if del {
			cuts = append(cuts, cut{d.start, d.end})
		}
	}
	sort.Slice(cuts, func(i, j int) bool { return cuts[i].s > cuts[j].s })
	out := append([]byte(nil), b...)
	for _, c := range cuts {
		e := c.e
		for e < len(out) && out[e] == '\n' {
			e++
		}
		out = append(out[:c.s], out[e:]...)
	}
	text := string(out)
	if strings.HasSuffix(path, "_codec_gen.go") {
		text = regexp.MustCompile(`(?m)^type (\w+JSONCodec) struct`).ReplaceAllString(text, "// +k8s:openapi-gen=false\ntype $1 struct")
	}
	text = re.ReplaceAllStringFunc(text, func(m string) string { return rename[m] })
	text = strings.ReplaceAll(text, "return resource.CopyObject(o)", "return o.DeepCopy()")
	if isObject {
		for _, k := range []string{"Job", "HistoricJob"} {
			if strings.HasSuffix(path, "/"+strings.ToLower(k)+"_object_gen.go") {
				text = emptySubresources(text, k)
			}
		}
	}
	// NewRepository() referenced the removed spec/status constructors
	text = regexp.MustCompile(`(?s)func New(Repository|Connection|Job|HistoricJob)\(\) \*\w+ \{.*?\n\}\n`).ReplaceAllStringFunc(text, func(m string) string {
		name := regexp.MustCompile(`func New(\w+)\(\)`).FindStringSubmatch(m)[1]
		return fmt.Sprintf("func New%s() *%s {\n\treturn &%s{}\n}\n", name, name, name)
	})

	lines := strings.Split(text, "\n")
	var res []string
	cur := ""
	for i := 0; i < len(lines); i++ {
		l := lines[i]
		if m := structRe.FindStringSubmatch(l); m != nil {
			cur = m[1]
			// markers for kinds and lists
			for _, k := range kinds {
				if cur == k {
					res = append(res, "// +genclient", "// +k8s:deepcopy-gen:interfaces=k8s.io/apimachinery/pkg/runtime.Object")
				}
				if cur == k+"List" {
					res = append(res, "// +k8s:deepcopy-gen:interfaces=k8s.io/apimachinery/pkg/runtime.Object")
				}
			}
		}
		if strings.HasPrefix(l, "}") {
			defer func() {}()
		}
		if isObject {
			l = normaliseKindTags(l, cur)
		}
		if m := fieldRe.FindStringSubmatch(l); m != nil && cur != "" {
			field, typ, tag := m[1], m[2], m[3]
			key := cur + "." + field
			if nn, ok := fieldNames[key]; ok {
				field = nn
				key = cur + "." + field
				for from, to := range fieldNames {
					_ = from
					_ = to
				}
			}
			if cur == "Repository" || cur == "Connection" || cur == "Job" || cur == "HistoricJob" {
				if field == "Secure" && isObject {
					st := "SecureValues"
					if cur == "Connection" {
						st = "ConnectionSecure"
					}
					l = fmt.Sprintf("\tSecure %s `json:\"secure,omitzero,omitempty\"`", st)
					res = append(res, l)
					continue
				}
				if field == "Items" {
					res = append(res, "\t// +listType=atomic")
				}
				res = append(res, l)
				continue
			}
			if t, ok := fieldTypes[key]; ok {
				typ = t
			} else if scalarPtr.MatchString(typ) && strings.Contains(tag, "omitempty") && !keepPointer[key] {
				typ = strings.TrimPrefix(typ, "*")
			} else if strings.HasPrefix(typ, "*") && isEnumName(strings.TrimPrefix(typ, "*")) && strings.Contains(tag, "omitempty") {
				typ = strings.TrimPrefix(typ, "*")
			}
			if key == "HistoricJobList.Items" {
				tag = "`json:\"items,omitempty\"`"
			}
			if t, ok := tagOverrides[key]; ok {
				tag = "`" + t + "`"
			}
			for _, mk := range extraMarkers[key] {
				res = append(res, "\t// "+mk)
			}
			if strings.HasPrefix(typ, "[]") && len(extraMarkers[key]) == 0 {
				res = append(res, "\t// +listType=atomic")
			}
			res = append(res, fmt.Sprintf("\t%s %s %s", field, typ, tag))
			continue
		}
		res = append(res, l)
	}
	text = strings.Join(res, "\n")
	if strings.Contains(text, "metav1.") && !strings.Contains(text, `metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"`) {
		text = strings.Replace(text, "package v0alpha1\n", "package v0alpha1\n\nimport metav1 \"k8s.io/apimachinery/pkg/apis/meta/v1\"\n", 1)
	}
	return []byte(text)
}

var enumNames = map[string]bool{}

func init() {
	for _, v := range handWritten {
		if v != "" && !strings.Contains(v, ".") && v != "ErrorDetails" {
			enumNames[v] = true
		}
	}
}

func isEnumName(n string) bool { return enumNames[n] }
